#include <stdint.h>

// Mandator: tohost symbol
extern volatile uint64_t tohost;

// Mandatory: stack symbols
uint64_t _stack[512]; // Main stack for main() function (4KB)
uint64_t * const _stack_top = _stack+512;

uint64_t _trap_stack[64]; // Dedicated trap stack (0.5KB)
uint64_t * const _trap_stack_top = _trap_stack+64;

// Function to measure cycles (assuming rdcycle is available)
static inline uint64_t rdcycle() {
    uint64_t cycles;
    // The 'memory' clobber ensures the compiler doesn't reorder memory operations
    // around rdcycle, which is crucial for accurate timing.
    asm volatile ("rdcycle %0" : "=r" (cycles) : : "memory");
    return cycles;
}

// NOP sled for pipeline settling
static inline void nops(int count) {
    for (int i = 0; i < count; i++) {
        asm volatile("nop");
    }
}

// Assume printf is available via libgloss or similar bare-metal library
// Use %lu for uint64_t as specified for this RV64 target.
int printf(const char* fmt, ...); // Declaration only

// Experiment specific constants
#define CACHE_BLOCK_BYTES 64
#define NUM_MONITORED_LINES 2
#define NUM_TRIALS_CHARACT 50 // Number of trials for statistical rigor
#define NUM_REPEATS_ACCESS 10 // Number of repeated accesses to ensure a line is in cache

// Declare static buffers. These will likely map to different L2 sets due to memory constraints.
// Each buffer is 64 bytes, cache line aligned. Total static data: 3 * 64 = 192 bytes (well within 16KB).
static volatile uint8_t monitored_line_0[CACHE_BLOCK_BYTES] __attribute__((aligned(CACHE_BLOCK_BYTES)));
static volatile uint8_t monitored_line_1[CACHE_BLOCK_BYTES] __attribute__((aligned(CACHE_BLOCK_BYTES)));
static volatile uint8_t trigger_line[CACHE_BLOCK_BYTES] __attribute__((aligned(CACHE_BLOCK_BYTES)));

// Arrays to store results for each monitored line, pre and post trigger
uint64_t results_pre_trigger[NUM_TRIALS_CHARACT][NUM_MONITORED_LINES];
uint64_t results_post_trigger[NUM_TRIALS_CHARACT][NUM_MONITORED_LINES];


// Main function for the experiment
void main() {
    printf("L2 Cache PRNG Characterization Experiment (Simplified)\n");
    printf("---------------------------------------------------\n");
    printf("Due to bare-metal memory constraints (total static data < 16KB, no single array > 8KB) and the inability to map multiple distinct lines to a single L2 set (512 sets, 8 ways, 64B lines), a full 8-way Prime+Probe on a single L2 set is not feasible.\n");
    printf("This experiment instead monitors two cache lines which will likely map to different L2 sets.\n");
    printf("It attempts to observe if an L2 access to a 'trigger_line' (also likely a different L2 set) affects these monitored lines by observing timing changes.\n");
    printf("The inability to reliably flush the L2 cache also means initial cache state is undefined, further limiting reliability for characterization.\n\n");

    for (int trial = 0; trial < NUM_TRIALS_CHARACT; trial++) {
        // Phase 1: Implicit Priming of monitored lines into L2
        // Access each line multiple times to increase the likelihood it's brought into the L2
        for (int i = 0; i < NUM_REPEATS_ACCESS; i++) {
            volatile uint8_t dummy_0 = monitored_line_0[0]; // Read monitored_line_0
            volatile uint8_t dummy_1 = monitored_line_1[0]; // Read monitored_line_1
            (void)dummy_0; // Suppress unused variable warning
            (void)dummy_1; // Suppress unused variable warning
            nops(8); // Settle pipeline
        }
        nops(64); // Larger NOP sled before measurement

        // Phase 2: Pre-Trigger Measurement - Measure access time for monitored lines
        uint64_t start_cycles_0 = rdcycle();
        volatile uint8_t dummy_0_pre = monitored_line_0[0];
        uint64_t end_cycles_0 = rdcycle();
        results_pre_trigger[trial][0] = end_cycles_0 - start_cycles_0;
        (void)dummy_0_pre;
        nops(8);

        uint64_t start_cycles_1 = rdcycle();
        volatile uint8_t dummy_1_pre = monitored_line_1[0];
        uint64_t end_cycles_1 = rdcycle();
        results_pre_trigger[trial][1] = end_cycles_1 - start_cycles_1;
        (void)dummy_1_pre;
        nops(64);

        // Phase 3: Trigger Event - Access a different line
        // This L2 access to 'trigger_line' is intended to potentially advance the PRNG state
        // or cause an eviction, even if it's in a different set.
        volatile uint8_t dummy_trigger = trigger_line[0];
        (void)dummy_trigger;
        nops(64); // Settle pipeline after trigger

        // Phase 4: Post-Trigger Measurement - Re-measure access time for monitored lines
        start_cycles_0 = rdcycle();
        volatile uint8_t dummy_0_post = monitored_line_0[0];
        uint64_t end_cycles_0 = rdcycle();
        results_post_trigger[trial][0] = end_cycles_0 - start_cycles_0;
        (void)dummy_0_post;
        nops(8);

        start_cycles_1 = rdcycle();
        volatile uint8_t dummy_1_post = monitored_line_1[0];
        uint64_t end_cycles_1 = rdcycle();
        results_post_trigger[trial][1] = end_cycles_1 - start_cycles_1;
        (void)dummy_1_post;
        nops(64);

        printf("Trial %lu: Line0_Pre=%lu, Line1_Pre=%lu, Line0_Post=%lu, Line1_Post=%lu\n",
               (uint64_t)trial,
               results_pre_trigger[trial][0],
               results_pre_trigger[trial][1],
               results_post_trigger[trial][0],
               results_post_trigger[trial][1]);
    }

    printf("\nRaw Results (Pre-Trigger):\n");
    for (int trial = 0; trial < NUM_TRIALS_CHARACT; trial++) {
        printf("%lu, %lu\n", results_pre_trigger[trial][0], results_pre_trigger[trial][1]);
    }

    printf("\nRaw Results (Post-Trigger):\n");
    for (int trial = 0; trial < NUM_TRIALS_CHARACT; trial++) {
        printf("%lu, %lu\n", results_post_trigger[trial][0], results_post_trigger[trial][1]);
    }

    // MANDATORY simulation termination
    tohost = 1;
    while (1) {}
}

// Trap handler (minimal, required for bare-metal setup)
void _trap_vector() __attribute__((naked));
void _trap_vector() {
    // This is a minimal trap handler.
    // It saves the original stack pointer (SP) to mscratch, switches to a dedicated trap stack,
    // saves/restores minimal registers, and advances mepc for expected synchronous traps.
    asm volatile (
        "csrrw sp, mscratch, sp\n" // Save original SP to mscratch, switch to trap SP (from mscratch)
        "addi sp, sp, -16\n"       // Allocate minimal space on trap stack for ra, t0
        "sd ra, 0(sp)\n"           // Save return address
        "sd t0, 8(sp)\n"           // Save t0 (used by handler)

        "csrr t0, mcause\n" // Read the cause of the trap

        // Define common synchronous exception causes (e.g., ecall for printf, page faults)
        "li t1, 0x8\n" // Instruction page fault
        "li t2, 0xc\n" // Load page fault
        "li t3, 0xf\n" // Store/AMO page fault
        "li t4, 0xb\n" // Environment Call from M-mode (ecall, potentially used by printf)

        // Check if mcause matches an expected exception
        "beq t0, t1, 1f\n" // If instruction page fault, advance mepc
        "beq t0, t2, 1f\n" // If load page fault, advance mepc
        "beq t0, t3, 1f\n" // If store page fault, advance mepc
        "beq t0, t4, 1f\n" // If ecall, advance mepc

        // Unhandled trap: loop indefinitely (simulation will likely timeout or report an error)
        "2:\n"
        "j 2b\n" // Loop back to label '2'

        "1:\n" // Label for advancing mepc for synchronous exceptions
        "csrr t0, mepc\n"
        "addi t0, t0, 4\n" // Advance mepc by 4 (instruction length for standard instructions)
        "csrw mepc, t0\n"

        // Restore saved registers
        "ld ra, 0(sp)\n"
        "ld t0, 8(sp)\n"
        "addi sp, sp, 16\n"       // Deallocate trap stack space
        "csrrw sp, mscratch, sp\n" // Restore original SP, mscratch gets current (trap) SP
        "mret\n"
    );
}

// Entry point for bare-metal C programs
void _start() {
    // 1. Set up the main stack pointer
    asm volatile("mv sp, %0" :: "r"(_stack_top));

    // 2. Set up mscratch to point to the dedicated trap stack
    asm volatile("csrw mscratch, %0" :: "r"(_trap_stack_top));

    // Call main function
    main();

    // In case main returns (which it shouldn't for this program),
    // terminate simulation to prevent infinite run.
    tohost = 1;
    while (1) {}
}

```

